 import React, { useState, useEffect } from 'react'
import { supabase } from '../../lib/supabase'
import { useAuth } from '../../contexts/AuthContext'
import { useToast } from '../../contexts/ToastContext'
import { useNavigate } from 'react-router-dom'

export default function AdminDashboard() {
    const { user, isAdmin, signOut } = useAuth()
    const { showToast } = useToast()
    const navigate = useNavigate()
    const [loading, setLoading] = useState(true)
    const [activeTab, setActiveTab] = useState('overview')
    const [stats, setStats] = useState({
        totalUsers: 0,
        totalCommunities: 0,
        totalPosts: 0,
        totalPredictions: 0,
        totalReports: 0
    })
    const [users, setUsers] = useState([])
    const [communities, setCommunities] = useState([])
    const [posts, setPosts] = useState([])
    const [reports, setReports] = useState([])

    // Redirect if not admin
    useEffect(() => {
        if (!isAdmin) {
            navigate('/')
            showToast('Access denied. Admin privileges required.', 'error')
        }
    }, [isAdmin])

    useEffect(() => {
        if (isAdmin) {
            loadDashboardData()
        }
    }, [isAdmin])

    const loadDashboardData = async () => {
        setLoading(true)
        try {
            // Load stats
            const [
                { count: userCount },
                { count: communityCount },
                { count: postCount },
                { count: predictionCount },
                { count: reportCount }
            ] = await Promise.all([
                supabase.from('profiles').select('*', { count: 'exact', head: true }),
                supabase.from('communities').select('*', { count: 'exact', head: true }),
                supabase.from('posts').select('*', { count: 'exact', head: true }),
                supabase.from('public_predictions').select('*', { count: 'exact', head: true }),
                supabase.from('reports').select('*', { count: 'exact', head: true })
            ])

            setStats({
                totalUsers: userCount || 0,
                totalCommunities: communityCount || 0,
                totalPosts: postCount || 0,
                totalPredictions: predictionCount || 0,
                totalReports: reportCount || 0
            })

            // Load users with email and phone
            const { data: usersData } = await supabase
                .from('profiles')
                .select('id, username, full_name, email, phone, role, created_at, is_banned')
                .order('created_at', { ascending: false })
                .limit(20)
            setUsers(usersData || [])

            // Load communities
            const { data: communitiesData } = await supabase
                .from('communities')
                .select('*, profiles:creator_id (username, full_name)')
                .order('created_at', { ascending: false })
                .limit(20)
            setCommunities(communitiesData || [])

            // Load posts
            const { data: postsData } = await supabase
                .from('posts')
                .select('*, profiles:user_id (username, full_name)')
                .order('created_at', { ascending: false })
                .limit(20)
            setPosts(postsData || [])

            // Load reports
            const { data: reportsData } = await supabase
                .from('reports')
                .select('*, profiles:reporter_id (username, full_name)')
                .eq('status', 'pending')
                .order('created_at', { ascending: false })
            setReports(reportsData || [])

        } catch (error) {
            console.error('Error loading dashboard:', error)
            showToast('Failed to load dashboard data', 'error')
        } finally {
            setLoading(false)
        }
    }

    const handleDeleteUser = async (userId) => {
        if (!window.confirm('Are you sure you want to permanently delete this user? This cannot be undone.')) return
        
        try {
            // Delete user from profiles (cascade will handle related data)
            await supabase.from('profiles').delete().eq('id', userId)
            showToast('User deleted successfully', 'success')
            loadDashboardData()
        } catch (error) {
            console.error('Error deleting user:', error)
            showToast('Failed to delete user: ' + error.message, 'error')
        }
    }

    const handleBanUser = async (userId) => {
        const reason = prompt('Reason for banning this user:')
        if (reason === null) return
        
        try {
            await supabase
                .from('profiles')
                .update({ 
                    is_banned: true, 
                    banned_at: new Date().toISOString(),
                    banned_reason: reason || 'Violation of terms'
                })
                .eq('id', userId)
            
            showToast('User banned successfully', 'success')
            loadDashboardData()
        } catch (error) {
            console.error('Error banning user:', error)
            showToast('Failed to ban user', 'error')
        }
    }

    const handleUnbanUser = async (userId) => {
        if (!window.confirm('Are you sure you want to unban this user?')) return
        
        try {
            await supabase
                .from('profiles')
                .update({ is_banned: false, banned_at: null, banned_reason: null })
                .eq('id', userId)
            
            showToast('User unbanned successfully', 'success')
            loadDashboardData()
        } catch (error) {
            console.error('Error unbanning user:', error)
            showToast('Failed to unban user', 'error')
        }
    }

    const handleDeletePost = async (postId) => {
        if (!window.confirm('Are you sure you want to permanently delete this post? This will also delete all comments and reactions.')) return
        
        try {
            // Delete in correct order to avoid foreign key issues
            // 1. Delete post reactions
            await supabase
                .from('post_reactions')
                .delete()
                .eq('post_id', postId)
            
            // 2. Delete comment replies
            const { data: comments } = await supabase
                .from('post_comments')
                .select('id')
                .eq('post_id', postId)
            
            if (comments && comments.length > 0) {
                const commentIds = comments.map(c => c.id)
                await supabase
                    .from('comment_replies')
                    .delete()
                    .in('comment_id', commentIds)
            }
            
            // 3. Delete comments
            await supabase
                .from('post_comments')
                .delete()
                .eq('post_id', postId)
            
            // 4. Finally delete the post
            const { error } = await supabase
                .from('posts')
                .delete()
                .eq('id', postId)
            
            if (error) throw error
            
            showToast('Post and all associated data deleted successfully', 'success')
            loadDashboardData()
        } catch (error) {
            console.error('Error deleting post:', error)
            showToast('Failed to delete post: ' + error.message, 'error')
        }
    }

    const handleDeleteCommunity = async (communityId) => {
        if (!window.confirm('Are you sure you want to delete this community? This will delete all posts, comments, and member data.')) return
        
        try {
            // Delete community (cascade will handle related data)
            await supabase.from('communities').delete().eq('id', communityId)
            showToast('Community deleted successfully', 'success')
            loadDashboardData()
        } catch (error) {
            console.error('Error deleting community:', error)
            showToast('Failed to delete community: ' + error.message, 'error')
        }
    }

    const handleResolveReport = async (reportId) => {
        try {
            await supabase
                .from('reports')
                .update({ 
                    status: 'resolved', 
                    resolved_at: new Date().toISOString(),
                    resolved_by: user.id
                })
                .eq('id', reportId)
            
            showToast('Report resolved', 'success')
            loadDashboardData()
        } catch (error) {
            console.error('Error resolving report:', error)
            showToast('Failed to resolve report', 'error')
        }
    }

    const handleDismissReport = async (reportId) => {
        if (!window.confirm('Are you sure you want to dismiss this report?')) return
        
        try {
            await supabase
                .from('reports')
                .update({ 
                    status: 'dismissed', 
                    resolved_at: new Date().toISOString(),
                    resolved_by: user.id
                })
                .eq('id', reportId)
            
            showToast('Report dismissed', 'success')
            loadDashboardData()
        } catch (error) {
            console.error('Error dismissing report:', error)
            showToast('Failed to dismiss report', 'error')
        }
    }

    const handleSignOut = async () => {
        await signOut()
        navigate('/login')
    }

    if (loading) {
        return (
            <div className="text-center py-12">
                <div className="text-gray-500">Loading dashboard...</div>
            </div>
        )
    }

    return (
        <div className="min-h-screen bg-gray-100">
            {/* Admin Navbar */}
            <nav className="bg-purple-700 text-white shadow-lg sticky top-0 z-50">
                <div className="max-w-7xl mx-auto px-4">
                    <div className="flex justify-between items-center h-16">
                        <div className="flex items-center gap-2">
                            <span className="text-2xl">🛡️</span>
                            <span className="font-bold text-xl">Admin Panel</span>
                        </div>
                        <div className="flex items-center gap-4">
                            <span className="text-sm">{user?.email}</span>
                            <button
                                onClick={handleSignOut}
                                className="bg-red-600 hover:bg-red-700 px-4 py-2 rounded-lg text-sm transition"
                            >
                                Sign Out
                            </button>
                        </div>
                    </div>
                </div>
            </nav>

            <div className="max-w-7xl mx-auto px-4 py-8">
                {/* Stats Cards */}
                <div className="grid grid-cols-2 md:grid-cols-5 gap-4 mb-8">
                    <div className="bg-white rounded-xl shadow-md p-4 text-center">
                        <div className="text-2xl font-bold text-purple-600">{stats.totalUsers}</div>
                        <div className="text-sm text-gray-500">Users</div>
                    </div>
                    <div className="bg-white rounded-xl shadow-md p-4 text-center">
                        <div className="text-2xl font-bold text-blue-600">{stats.totalCommunities}</div>
                        <div className="text-sm text-gray-500">Communities</div>
                    </div>
                    <div className="bg-white rounded-xl shadow-md p-4 text-center">
                        <div className="text-2xl font-bold text-green-600">{stats.totalPosts}</div>
                        <div className="text-sm text-gray-500">Posts</div>
                    </div>
                    <div className="bg-white rounded-xl shadow-md p-4 text-center">
                        <div className="text-2xl font-bold text-yellow-600">{stats.totalPredictions}</div>
                        <div className="text-sm text-gray-500">Predictions</div>
                    </div>
                    <div className="bg-white rounded-xl shadow-md p-4 text-center cursor-pointer hover:shadow-lg transition">
                        <div className="text-2xl font-bold text-red-600">{stats.totalReports}</div>
                        <div className="text-sm text-gray-500">Reports</div>
                    </div>
                </div>

                {/* Tabs */}
                <div className="flex gap-2 mb-6 overflow-x-auto">
                    <button
                        onClick={() => setActiveTab('overview')}
                        className={`px-4 py-2 rounded-lg text-sm font-medium transition ${
                            activeTab === 'overview' 
                                ? 'bg-purple-600 text-white' 
                                : 'bg-gray-200 text-gray-700 hover:bg-gray-300'
                        }`}
                    >
                        📊 Overview
                    </button>
                    <button
                        onClick={() => setActiveTab('users')}
                        className={`px-4 py-2 rounded-lg text-sm font-medium transition ${
                            activeTab === 'users' 
                                ? 'bg-purple-600 text-white' 
                                : 'bg-gray-200 text-gray-700 hover:bg-gray-300'
                        }`}
                    >
                        👥 Users ({stats.totalUsers})
                    </button>
                    <button
                        onClick={() => setActiveTab('communities')}
                        className={`px-4 py-2 rounded-lg text-sm font-medium transition ${
                            activeTab === 'communities' 
                                ? 'bg-purple-600 text-white' 
                                : 'bg-gray-200 text-gray-700 hover:bg-gray-300'
                        }`}
                    >
                        🏛️ Communities ({stats.totalCommunities})
                    </button>
                    <button
                        onClick={() => setActiveTab('posts')}
                        className={`px-4 py-2 rounded-lg text-sm font-medium transition ${
                            activeTab === 'posts' 
                                ? 'bg-purple-600 text-white' 
                                : 'bg-gray-200 text-gray-700 hover:bg-gray-300'
                        }`}
                    >
                        📝 Posts ({stats.totalPosts})
                    </button>
                    <button
                        onClick={() => setActiveTab('reports')}
                        className={`px-4 py-2 rounded-lg text-sm font-medium transition ${
                            activeTab === 'reports' 
                                ? 'bg-purple-600 text-white' 
                                : 'bg-gray-200 text-gray-700 hover:bg-gray-300'
                        }`}
                    >
                        🚨 Reports ({stats.totalReports})
                    </button>
                </div>

                {/* OVERVIEW TAB */}
                {activeTab === 'overview' && (
                    <div className="bg-white rounded-xl shadow-md p-6">
                        <h2 className="text-xl font-bold text-gray-800 mb-4">📊 Platform Overview</h2>
                        <p className="text-gray-500">Welcome to the admin dashboard. Use the tabs above to manage users, communities, posts, and reports.</p>
                        <div className="mt-4 grid grid-cols-1 md:grid-cols-3 gap-4">
                            <div className="bg-purple-50 rounded-lg p-4">
                                <div className="text-sm text-gray-500">Total Revenue</div>
                                <div className="text-2xl font-bold text-purple-600">
                                    R{(stats.totalCommunities || 0) * 25}.00
                                </div>
                                <div className="text-xs text-gray-400">From community subscriptions</div>
                            </div>
                            <div className="bg-green-50 rounded-lg p-4">
                                <div className="text-sm text-gray-500">Active Users</div>
                                <div className="text-2xl font-bold text-green-600">
                                    {stats.totalUsers}
                                </div>
                            </div>
                            <div className="bg-blue-50 rounded-lg p-4">
                                <div className="text-sm text-gray-500">Total Communities</div>
                                <div className="text-2xl font-bold text-blue-600">
                                    {stats.totalCommunities}
                                </div>
                            </div>
                        </div>
                    </div>
                )}

                {/* USERS TAB */}
                {activeTab === 'users' && (
                    <div className="bg-white rounded-xl shadow-md overflow-hidden">
                        <div className="overflow-x-auto">
                            <table className="w-full">
                                <thead className="bg-gray-50">
                                    <tr>
                                        <th className="px-4 py-3 text-left text-sm font-semibold text-gray-600">User</th>
                                        <th className="px-4 py-3 text-left text-sm font-semibold text-gray-600">Email</th>
                                        <th className="px-4 py-3 text-left text-sm font-semibold text-gray-600">Phone</th>
                                        <th className="px-4 py-3 text-left text-sm font-semibold text-gray-600">Role</th>
                                        <th className="px-4 py-3 text-left text-sm font-semibold text-gray-600">Status</th>
                                        <th className="px-4 py-3 text-left text-sm font-semibold text-gray-600">Actions</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-gray-200">
                                    {users.map(userItem => (
                                        <tr key={userItem.id}>
                                            <td className="px-4 py-3">
                                                <div className="flex items-center gap-2">
                                                    <div className="w-8 h-8 bg-purple-500 rounded-full flex items-center justify-center text-white text-sm font-bold">
                                                        {userItem.username?.[0]?.toUpperCase() || 'U'}
                                                    </div>
                                                    <span className="font-medium">{userItem.full_name || userItem.username}</span>
                                                </div>
                                            </td>
                                            <td className="px-4 py-3 text-sm text-gray-600">{userItem.email || 'N/A'}</td>
                                            <td className="px-4 py-3 text-sm text-gray-600">{userItem.phone || 'N/A'}</td>
                                            <td className="px-4 py-3">
                                                <span className={`text-xs px-2 py-1 rounded-full ${userItem.role === 'admin' ? 'bg-purple-100 text-purple-700' : 'bg-gray-100 text-gray-700'}`}>
                                                    {userItem.role || 'user'}
                                                </span>
                                            </td>
                                            <td className="px-4 py-3">
                                                {userItem.is_banned ? (
                                                    <span className="text-xs bg-red-100 text-red-700 px-2 py-1 rounded-full">🚫 Banned</span>
                                                ) : (
                                                    <span className="text-xs bg-green-100 text-green-700 px-2 py-1 rounded-full">✅ Active</span>
                                                )}
                                            </td>
                                            <td className="px-4 py-3">
                                                <div className="flex flex-wrap gap-1">
                                                    {userItem.is_banned ? (
                                                        <button
                                                            onClick={() => handleUnbanUser(userItem.id)}
                                                            className="text-green-500 hover:text-green-700 text-sm"
                                                            disabled={userItem.role === 'admin'}
                                                        >
                                                            Unban
                                                        </button>
                                                    ) : (
                                                        <button
                                                            onClick={() => handleBanUser(userItem.id)}
                                                            className="text-orange-500 hover:text-orange-700 text-sm"
                                                            disabled={userItem.role === 'admin'}
                                                        >
                                                            Ban
                                                        </button>
                                                    )}
                                                    <button
                                                        onClick={() => handleDeleteUser(userItem.id)}
                                                        className="text-red-500 hover:text-red-700 text-sm"
                                                        disabled={userItem.role === 'admin'}
                                                    >
                                                        🗑️ Delete
                                                    </button>
                                                </div>
                                            </td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                    </div>
                )}

                {/* COMMUNITIES TAB */}
                {activeTab === 'communities' && (
                    <div className="bg-white rounded-xl shadow-md overflow-hidden">
                        <div className="overflow-x-auto">
                            <table className="w-full">
                                <thead className="bg-gray-50">
                                    <tr>
                                        <th className="px-4 py-3 text-left text-sm font-semibold text-gray-600">Community</th>
                                        <th className="px-4 py-3 text-left text-sm font-semibold text-gray-600">Creator</th>
                                        <th className="px-4 py-3 text-left text-sm font-semibold text-gray-600">Members</th>
                                        <th className="px-4 py-3 text-left text-sm font-semibold text-gray-600">Posts</th>
                                        <th className="px-4 py-3 text-left text-sm font-semibold text-gray-600">Actions</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-gray-200">
                                    {communities.map(community => (
                                        <tr key={community.id}>
                                            <td className="px-4 py-3 font-medium">{community.name}</td>
                                            <td className="px-4 py-3 text-sm text-gray-600">{community.profiles?.username || 'Unknown'}</td>
                                            <td className="px-4 py-3 text-sm">{community.member_count || 0}</td>
                                            <td className="px-4 py-3 text-sm">{community.post_count || 0}</td>
                                            <td className="px-4 py-3">
                                                <button
                                                    onClick={() => handleDeleteCommunity(community.id)}
                                                    className="text-red-500 hover:text-red-700 text-sm"
                                                >
                                                    🗑️ Delete
                                                </button>
                                            </td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                    </div>
                )}

                {/* POSTS TAB */}
                {activeTab === 'posts' && (
                    <div className="bg-white rounded-xl shadow-md overflow-hidden">
                        <div className="overflow-x-auto">
                            <table className="w-full">
                                <thead className="bg-gray-50">
                                    <tr>
                                        <th className="px-4 py-3 text-left text-sm font-semibold text-gray-600">Post</th>
                                        <th className="px-4 py-3 text-left text-sm font-semibold text-gray-600">Author</th>
                                        <th className="px-4 py-3 text-left text-sm font-semibold text-gray-600">Likes</th>
                                        <th className="px-4 py-3 text-left text-sm font-semibold text-gray-600">Comments</th>
                                        <th className="px-4 py-3 text-left text-sm font-semibold text-gray-600">Actions</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-gray-200">
                                    {posts.map(post => (
                                        <tr key={post.id}>
                                            <td className="px-4 py-3 text-sm max-w-xs truncate">{post.text || 'No text'}</td>
                                            <td className="px-4 py-3 text-sm text-gray-600">{post.profiles?.username || 'Unknown'}</td>
                                            <td className="px-4 py-3 text-sm">{post.likes_count || 0}</td>
                                            <td className="px-4 py-3 text-sm">{post.comments_count || 0}</td>
                                            <td className="px-4 py-3">
                                                <button
                                                    onClick={() => handleDeletePost(post.id)}
                                                    className="text-red-500 hover:text-red-700 text-sm"
                                                >
                                                    🗑️ Delete
                                                </button>
                                            </td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                    </div>
                )}

                {/* REPORTS TAB */}
                {activeTab === 'reports' && (
                    <div className="bg-white rounded-xl shadow-md overflow-hidden">
                        {reports.length === 0 ? (
                            <div className="text-center py-12">
                                <div className="text-4xl mb-4">✅</div>
                                <p className="text-gray-500">No pending reports</p>
                                <p className="text-sm text-gray-400">All reports have been resolved</p>
                            </div>
                        ) : (
                            <div className="overflow-x-auto">
                                <table className="w-full">
                                    <thead className="bg-gray-50">
                                        <tr>
                                            <th className="px-4 py-3 text-left text-sm font-semibold text-gray-600">Reported By</th>
                                            <th className="px-4 py-3 text-left text-sm font-semibold text-gray-600">Reason</th>
                                            <th className="px-4 py-3 text-left text-sm font-semibold text-gray-600">Description</th>
                                            <th className="px-4 py-3 text-left text-sm font-semibold text-gray-600">Created</th>
                                            <th className="px-4 py-3 text-left text-sm font-semibold text-gray-600">Actions</th>
                                        </tr>
                                    </thead>
                                    <tbody className="divide-y divide-gray-200">
                                        {reports.map(report => (
                                            <tr key={report.id}>
                                                <td className="px-4 py-3 text-sm">{report.profiles?.username || 'Unknown'}</td>
                                                <td className="px-4 py-3 text-sm font-medium text-red-600">{report.reason}</td>
                                                <td className="px-4 py-3 text-sm max-w-xs truncate">{report.description || 'No description'}</td>
                                                <td className="px-4 py-3 text-sm text-gray-500">{new Date(report.created_at).toLocaleDateString()}</td>
                                                <td className="px-4 py-3">
                                                    <div className="flex gap-2">
                                                        <button
                                                            onClick={() => handleResolveReport(report.id)}
                                                            className="text-green-500 hover:text-green-700 text-sm"
                                                        >
                                                            ✅ Resolve
                                                        </button>
                                                        <button
                                                            onClick={() => handleDismissReport(report.id)}
                                                            className="text-gray-500 hover:text-gray-700 text-sm"
                                                        >
                                                            Dismiss
                                                        </button>
                                                    </div>
                                                </td>
                                            </tr>
                                        ))}
                                    </tbody>
                                </table>
                            </div>
                        )}
                    </div>
                )}
            </div>
        </div>
    )
}
